import{_ as a,o as e,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"Go · 03 框架与生态","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/go/03-frameworks.md","filePath":"tech-system/backend/go/03-frameworks.md"}'),i={name:"tech-system/backend/go/03-frameworks.md"};function o(n,t,h,l,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="go-·-03-框架与生态" tabindex="-1">Go · 03 框架与生态 <a class="header-anchor" href="#go-·-03-框架与生态" aria-label="Permalink to “Go · 03 框架与生态”">​</a></h1><h2 id="_1-标准库-net-http" tabindex="-1">1. 标准库 net/http <a class="header-anchor" href="#_1-标准库-net-http" aria-label="Permalink to “1. 标准库 net/http”">​</a></h2><p>很多场景 <strong>甚至不需要框架</strong>：依赖少、行为可控、长期可读。</p><p>适合：内部小工具、探针、简单 API。</p><h2 id="_2-gin" tabindex="-1">2. Gin <a class="header-anchor" href="#_2-gin" aria-label="Permalink to “2. Gin”">​</a></h2><ul><li>轻量、路由清晰，国内资料多</li><li>写小 API 的常用选择</li><li>中间件、绑定、校验够用</li></ul><h2 id="_3-echo-fiber" tabindex="-1">3. Echo / Fiber <a class="header-anchor" href="#_3-echo-fiber" aria-label="Permalink to “3. Echo / Fiber”">​</a></h2><ul><li>Echo：中间件与生态成熟度不错</li><li>Fiber：Express 风格，追求性能与上手速度</li></ul><p><strong>判断：</strong> 小服务用 Gin 或标准库足够；不必三个都精通。读别人项目时能看懂即可。</p><hr><h2 id="_4-周边" tabindex="-1">4. 周边 <a class="header-anchor" href="#_4-周边" aria-label="Permalink to “4. 周边”">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>常见选择</th></tr></thead><tbody><tr><td>配置</td><td>env / viper（按需）</td></tr><tr><td>日志</td><td>slog（新标准）/ zap</td></tr><tr><td>DB</td><td>database/sql + 轻封装；重 ORM 谨慎</td></tr><tr><td>路由生态</td><td>chi 等也很常见</td></tr></tbody></table><p>原则：<strong>Go 框架够用就行</strong>，深度让给 Java/Spring 与 <a href="./../problems/">后端问题</a> 沉淀。</p><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>练习 / 小工具 API</td><td>Gin 或标准库</td></tr><tr><td>读别人项目</td><td>能看懂 Gin/Echo 即可</td></tr><tr><td>生产主业务</td><td>仍默认 <strong>Java</strong></td></tr></tbody></table><p>下一篇：<a href="./04-engineering.html">04 工程实践</a></p>',15)])])}const _=a(i,[["render",o]]);export{p as __pageData,_ as default};
